sp_theme.css_variables:
:root {
  --cp-navy:   #0A2540;
  --cp-gold:   #C5A065;
  --cp-teal:   #14B8A6;
  --cp-bg:     #F7F9FC;
  --cp-line:   #DDE5EE;
  --cp-muted:  #5E6D7E;
  --cp-danger: #C0392B;
  --cp-card-shadow: 0 1px 2px rgba(10,37,64,.04), 0 8px 24px rgba(10,37,64,.06);
  --cp-font: "Aptos","Segoe UI",system-ui,-apple-system,sans-serif;
}

body, .sp-page-root {
  background: var(--cp-bg);
  color: var(--cp-navy);
  font-family: var(--cp-font);
}

/* ---- Buttons ---- */
.cp-btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 44px; padding: 0 22px; border-radius: 10px;
  font-weight: 750; font-size: 14px; text-decoration: none;
  border: 1px solid transparent; cursor: pointer; transition: .18s ease;
}
.cp-btn--primary { background: var(--cp-gold); color: #1c1404; }
.cp-btn--primary:hover { filter: brightness(1.05); transform: translateY(-1px); }
.cp-btn--secondary { background: #fff; color: var(--cp-navy); border-color: var(--cp-line); }
.cp-btn--secondary:hover { border-color: var(--cp-navy); }

/* ---- Cards / surfaces ---- */
.cp-card {
  background: #fff; border: 1px solid var(--cp-line);
  border-radius: 14px; box-shadow: var(--cp-card-shadow);
}

/* ---- Eyebrow / section headings ---- */
.cp-eyebrow {
  color: var(--cp-gold); font-size: 12px; font-weight: 850;
  letter-spacing: .11em; text-transform: uppercase; margin-bottom: 10px;
}
.cp-h2 { font-size: 26px; font-weight: 850; letter-spacing: -.01em; margin: 0 0 6px; }
.cp-sub { color: var(--cp-muted); font-size: 14px; margin: 0; }

/* ---- Status badges (used by every widget) ---- */
.cp-badge {
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 26px; padding: 0 12px; border-radius: 999px;
  font-size: 12px; font-weight: 800; letter-spacing: .02em;
  border: 1px solid transparent;
}
.cp-badge::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
.cp-badge--new       { color: var(--cp-navy);   background: rgba(10,37,64,.07);  border-color: rgba(10,37,64,.18); }
.cp-badge--review    { color: #8a6d2f;          background: rgba(197,160,101,.14); border-color: rgba(197,160,101,.5); }
.cp-badge--invest    { color: #8a6d2f;          background: rgba(197,160,101,.18); border-color: rgba(197,160,101,.6); }
.cp-badge--approved  { color: #08796F;          background: rgba(20,184,166,.14); border-color: rgba(20,184,166,.5); }
.cp-badge--rejected  { color: var(--cp-danger); background: rgba(192,57,43,.10);  border-color: rgba(192,57,43,.4); }
.cp-badge--closed    { color: var(--cp-muted);  background: rgba(94,109,126,.10); border-color: rgba(94,109,126,.35); }
